mapper.insert:
INSERT INTO image_tag(image_id, tag_id)
SELECT DISTINCT i.id, #{targetTagId}
FROM image i
INNER JOIN image_tag source_it ON source_it.image_id = i.id AND source_it.tag_id = #{sourceTagId}
LEFT JOIN image_tag target_it ON target_it.image_id = i.id AND target_it.tag_id = #{targetTagId}
WHERE i.user_id = #{userId}
  AND target_it.image_id IS NULL

